import heapq


def _dependency_solver(data, name_order, maximize):
    packages = data["packages"]
    names = sorted(packages, reverse=(name_order == "descending"))
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    roots = data["roots"]
    rows_by_name = {}
    choices = []

    for name in names:
        rows = {row["version"]: row for row in packages[name]}
        rows_by_name[name] = rows
        versions = [v for v in rows
                    if v not in blocked.get(name, [])
                    and (name not in pins or v == pins[name])]
        if name in roots:
            lo, hi = roots[name]
            versions = [v for v in versions if lo <= v <= hi]
        choices.append([-1] + versions)

    best_score = None
    best_versions = None
    for assignment in product(*choices):
        installed = {name: version for name, version in zip(names, assignment)
                     if version != -1}
        if any(name not in installed for name in roots):
            continue

        graph = {}
        valid = True
        for name, version in installed.items():
            row = rows_by_name[name][version]
            deps = [dep for dep in row.get("deps", [])
                    if not dep.get("feature") or dep["feature"] in features]
            active_names = []
            for dep in deps:
                target = dep["name"]
                selected = installed.get(target)
                if selected is None or not dep["min"] <= selected <= dep["max"]:
                    valid = False
                    break
                active_names.append(target)
            if not valid:
                break
            graph[name] = active_names
        if not valid:
            continue

        # The installed set must be exactly the closure reached from roots.
        reached = set()
        stack = list(roots)
        while stack:
            name = stack.pop()
            if name in reached:
                continue
            reached.add(name)
            stack.extend(graph.get(name, []))
        if reached != set(installed):
            continue

        # Reject cycles in the selected active dependency graph.
        state = {}
        def visit(name):
            mark = state.get(name, 0)
            if mark == 1:
                return False
            if mark == 2:
                return True
            state[name] = 1
            for other in graph.get(name, []):
                if not visit(other):
                    return False
            state[name] = 2
            return True

        if not all(visit(name) for name in installed):
            continue

        score = tuple(assignment)
        if best_score is None or (score > best_score if maximize else score < best_score):
            best_score = score
            best_versions = installed

    return {"versions": best_versions} if best_versions is not None else {"error": "unsatisfiable"}


def _component_01(data):
    return _dependency_solver(data, "descending", False)


